import { ArrowDropUp } from '@mui/icons-material';
import { Button, ClickAwayListener, Grow, MenuItem, MenuList, Paper, Popper } from '@mui/material';
import { t } from 'i18next';
import { useRef, useState } from 'react';
import useBreakpoint from '@/hooks/useBreakpoint';

interface RollOptionsMenuProps {
  selectedRoll: string;
  handleMenuItemClick: (value: string) => void;
  /** Hands-Free is Solo + Shared Device only — see CONTEXT.md "Hands-Free". */
  showHandsFree?: boolean;
}

const RollOptionsMenu = ({
  selectedRoll,
  handleMenuItemClick,
  showHandsFree = false,
}: RollOptionsMenuProps): JSX.Element => {
  const [open, setOpen] = useState<boolean>(false);
  const [anchorEl, setAnchorEl] = useState<HTMLElement | null>(null);
  const anchorRef = useRef<HTMLButtonElement>(null);
  const isMobile = useBreakpoint();

  const handleToggle = (): void => {
    setAnchorEl(anchorRef.current);
    setOpen((prevOpen) => !prevOpen);
  };

  const handleClose = (event: Event | React.SyntheticEvent): void => {
    if (event.target instanceof Node && anchorRef.current?.contains(event.target)) {
      return;
    }
    setOpen(false);
    setAnchorEl(null);
  };

  const options = new Map<string, string>();
  options.set('restart', t('restart')).set('manual', t('manual')).set('autoRoll', t('autoRoll'));
  if (showHandsFree) {
    options.set('handsFree', t('handsFree'));
  }

  const isSelected = (key: string): boolean =>
    key === 'autoRoll' ? ['30', '60', '90', 'custom'].includes(selectedRoll) : key === selectedRoll;

  return (
    <>
      <Button
        size="small"
        aria-controls={open ? 'split-button-menu' : undefined}
        aria-expanded={open ? 'true' : undefined}
        aria-label="select roll options"
        aria-haspopup="menu"
        onClick={handleToggle}
        ref={anchorRef}
      >
        <ArrowDropUp />
      </Button>
      <Popper
        sx={(theme) => ({ zIndex: theme.zIndex.tooltip + 1 })}
        open={open}
        anchorEl={anchorEl}
        transition
        disablePortal
        // Opening upward would cover a third of the video panel on a phone, where
        // the roll button sits directly beneath it.
        placement={isMobile ? 'bottom-end' : 'top-end'}
      >
        {({ TransitionProps }) => (
          <Grow
            {...TransitionProps}
            style={{ transformOrigin: isMobile ? 'right top' : 'right bottom' }}
          >
            <Paper>
              <ClickAwayListener onClickAway={handleClose}>
                <MenuList id="split-button-menu" autoFocusItem>
                  {Array.from(options).map(([key, option]) => (
                    <MenuItem
                      key={key}
                      selected={isSelected(key)}
                      onClick={() => handleMenuItemClick(key)}
                    >
                      {option}
                    </MenuItem>
                  ))}
                </MenuList>
              </ClickAwayListener>
            </Paper>
          </Grow>
        )}
      </Popper>
    </>
  );
};

export default RollOptionsMenu;
