import { DEFAULT_TILE_COUNT } from '@/constants/boardConstants';
import { Box, Button, Chip, IconButton, Popover, Typography } from '@mui/material';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import ScheduleIcon from '@mui/icons-material/Schedule';
import { Trans, useTranslation } from 'react-i18next';
import { generateSystemSummary, isSystemMessageLikelyToWrap } from '@/utils/messageUtils';
import { isPublicRoom } from '@/helpers/strings';
import { useCallback, useMemo, useState } from 'react';

import ActionText from './actionText';
import CopyToClipboard from '@/components/CopyToClipboard';
import DeleteMessageButton from '@/components/DeleteMessageButton';
import GameOverScreen from '@/components/GameOverScreen';
import { resolveFinishOutcome } from '@/helpers/finishOutcome';
import { getTurnFields } from '@/helpers/actionTurn';
import { Link } from 'react-router-dom';
import Markdown from 'react-markdown';
import { Message as MessageType, Base64ImageObject, isActionsMessage } from '@/types/Message';
import ShareIcon from '@mui/icons-material/Share';
import TextAvatar from '@/components/TextAvatar';
import clsx from 'clsx';
import dayjs from 'dayjs';
import { getDayjsWithLocale } from '@/helpers/momentLocale';
import { parseMessageTimestamp } from '@/helpers/timestamp';
import remarkGemoji from 'remark-gemoji';
import remarkGfm from 'remark-gfm';

const MILLISECONDS_IN_A_MINUTE = 60000;

// Type guard to check if image is a Base64ImageObject
function isBase64ImageObject(image: unknown): image is Base64ImageObject {
  return (
    typeof image === 'object' &&
    image !== null &&
    'base64String' in image &&
    'format' in image &&
    typeof (image as Base64ImageObject).base64String === 'string' &&
    typeof (image as Base64ImageObject).format === 'string'
  );
}

interface MessageProps {
  message: MessageType;
  isOwnMessage: boolean;
  isTransparent?: boolean;
  currentGameBoardSize?: number;
  room: string;
}

export default function Message({
  message,
  isOwnMessage,
  isTransparent,
  currentGameBoardSize = DEFAULT_TILE_COUNT,
  room,
}: MessageProps): JSX.Element {
  const { t, i18n } = useTranslation();

  const [isOpenDialog, setIsOpenDialog] = useState<boolean>(false);
  const [detailsAnchor, setDetailsAnchor] = useState<HTMLElement | null>(null);

  const closeDialog = useCallback(() => {
    setIsOpenDialog(false);
  }, []);

  const handleDetailsClick = useCallback((event: React.MouseEvent<HTMLElement>) => {
    setDetailsAnchor(event.currentTarget);
  }, []);

  const handleDetailsClose = useCallback(() => {
    setDetailsAnchor(null);
  }, []);

  // Destructure common properties
  const { id, displayName, text, uid, timestamp, pending } = message;

  // Then conditionally access type-specific properties using discriminated union
  let boardSize: number | undefined;
  let gameBoardId: string | undefined;

  if (message.type === 'settings' || message.type === 'room') {
    // TypeScript knows these properties exist on settings and room messages
    boardSize = message.boardSize;
    gameBoardId = message.gameBoardId;
  }

  // Public rooms adopt the imported board's size (see useUrlImport), so any
  // shared board is importable there. Private rooms still require a size match.
  const isImportable =
    message.type === 'settings' && (isPublicRoom(room) || boardSize === currentGameBoardSize);

  // Memoize import board URL construction
  const importBoardUrl = useMemo(() => {
    if (!gameBoardId) {
      return undefined;
    }
    try {
      const url = new URL(window.location.href);
      url.searchParams.set('importBoard', gameBoardId);
      return url.toString();
    } catch {
      return undefined;
    }
  }, [gameBoardId]);

  // Memoize time formatting with 1-minute precision to reduce re-renders
  const ago = useMemo(() => {
    const date = parseMessageTimestamp(timestamp);
    if (!date) return '';

    // Round to the nearest minute to reduce unnecessary re-renders
    const roundedTime = new Date(
      Math.floor(date.getTime() / MILLISECONDS_IN_A_MINUTE) * MILLISECONDS_IN_A_MINUTE
    );

    // Get dayjs instance with proper locale
    const currentLanguage = i18n.resolvedLanguage || i18n.language;
    const dayjsInstance = getDayjsWithLocale(roundedTime, currentLanguage);
    let result = dayjsInstance.fromNow();

    // Handle "in a few seconds" case by showing "a minute ago" instead
    // This check works across languages since we're looking for seconds-based results
    if (Math.abs(dayjsInstance.diff(dayjs(), 'seconds')) < 30) {
      result = dayjsInstance.subtract(1, 'minute').fromNow();
    }
    return result;
  }, [timestamp, i18n.language, i18n.resolvedLanguage]);

  // Memoize image processing with precise dependencies
  const imageSrc = useMemo((): string | false => {
    if (message.type !== 'media') return false;

    const media = message;
    const mediaImage = media.image;

    // Handle image object with base64String and format properties
    if (isBase64ImageObject(mediaImage)) {
      return `data:image/${mediaImage.format};base64,${mediaImage.base64String}`;
    }

    // Handle direct string URLs (fallback for old format or Firebase URLs)
    if (typeof mediaImage === 'string' && mediaImage) {
      return mediaImage;
    }

    // Handle old format where URL might be in text field
    if (typeof text === 'string' && text && text.startsWith('http')) {
      return text;
    }

    return false;
  }, [message, text]);

  // Memoize markdown content rendering with text hash for better performance
  const markdownContent = useMemo(() => {
    if (message.type === 'actions') return null;
    if (!text || text.trim() === '') return null;
    return <Markdown remarkPlugins={[remarkGfm, remarkGemoji]}>{text}</Markdown>;
  }, [text, message.type]);

  // Named turn fields for an actions message; undefined for every other type.
  const actionTurn = useMemo(() => {
    if (!isActionsMessage(message)) return undefined;
    return getTurnFields(message, { finishWord: t('finish'), startWord: t('start') });
  }, [message, t]);

  // Generate smart summary for system messages
  const systemSummary = useMemo(() => {
    return generateSystemSummary(message.type, text, t);
  }, [message.type, text, t]);

  // Check if this is a system message that should use compact layout
  const isSystemMessage = message.type === 'settings' || message.type === 'room';

  // Check if text is likely to wrap (long text or contains multiple words)
  const isLikelyToWrap = useMemo(() => {
    if (!isSystemMessage) return false;
    return isSystemMessageLikelyToWrap(displayName, systemSummary);
  }, [isSystemMessage, displayName, systemSummary]);

  // Render system message (settings/room) with compact layout
  if (isSystemMessage) {
    return (
      <li
        className={clsx(
          'message',
          'system-message',
          isTransparent && 'transparent',
          isLikelyToWrap && 'full-width'
        )}
        data-testid={`message-${id}`}
      >
        <Box component="div" sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
          <IconButton
            size="small"
            onClick={handleDetailsClick}
            aria-label="View details"
            data-testid={`details-button-${id}`}
          >
            <InfoOutlinedIcon fontSize="small" />
          </IconButton>
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography variant="body2" component="span" sx={{ lineHeight: 1.2 }}>
              <strong>{displayName}</strong> {systemSummary}
            </Typography>
            <Typography
              variant="caption"
              sx={{
                display: 'block',
                opacity: 0.7,
                fontSize: '0.65rem',
                mt: 0.25,
              }}
            >
              {ago}
            </Typography>
          </Box>
        </Box>
        {/* Details Popover */}
        <Popover
          open={Boolean(detailsAnchor)}
          anchorEl={detailsAnchor}
          onClose={handleDetailsClose}
          anchorOrigin={{
            vertical: 'bottom',
            horizontal: 'center',
          }}
          transformOrigin={{
            vertical: 'top',
            horizontal: 'center',
          }}
          data-testid={`details-popover-${id}`}
        >
          <Box className="system-details-popover">
            <div className="system-details-content">
              {/* Floats onto the heading line the markdown renders first, so the
                  board's size reads as part of the title row. Comes from the
                  message metadata, which every shared board carries. */}
              {message.type === 'settings' && !!boardSize && (
                <Typography
                  variant="body2"
                  className="system-details-size"
                  data-testid={`board-size-${id}`}
                >
                  {t('tilesCount', { count: boardSize })}
                </Typography>
              )}
              {markdownContent}
            </div>

            {message.type === 'settings' && (
              <Box className="system-action-buttons">
                {isImportable ? (
                  <Box
                    sx={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                      gap: 1,
                    }}
                  >
                    <Button
                      component={Link}
                      to={`?importBoard=${gameBoardId}`}
                      variant="contained"
                      size="small"
                      color="primary"
                    >
                      <Trans i18nKey="importBoard" />
                    </Button>
                    <CopyToClipboard
                      text={importBoardUrl || ''}
                      copiedText={t('copiedBoardLink')}
                      tooltip={t('copyBoardLink')}
                      icon={<ShareIcon />}
                    />
                  </Box>
                ) : (
                  <Typography
                    variant="body2"
                    sx={{
                      color: 'text.secondary',
                    }}
                  >
                    <Trans i18nKey="incompatibleBoard" />
                  </Typography>
                )}
              </Box>
            )}

            {message.type === 'room' && (
              <Box className="system-action-buttons">
                <Box
                  sx={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    gap: 1,
                  }}
                >
                  <Typography variant="body2">
                    {t('room')}: <strong>{room}</strong>
                  </Typography>
                  <CopyToClipboard
                    text={window.location.href}
                    copiedText={t('copiedRoomLink')}
                    tooltip={t('copyRoomLink')}
                    icon={<ShareIcon />}
                  />
                </Box>
              </Box>
            )}
          </Box>
        </Popover>
      </li>
    );
  }

  // Render regular message (chat, actions, media) with standard layout
  return (
    <li
      className={clsx('message', isOwnMessage && 'own-message', isTransparent && 'transparent')}
      data-testid={`message-${id}`}
    >
      <div className="message-header">
        <div className="sender">
          <TextAvatar uid={uid} displayName={displayName} size="small" />
          <span className="sender-name">{displayName}</span>
          {pending ? (
            <Chip
              icon={<ScheduleIcon />}
              label={t('messagePending')}
              size="small"
              variant="outlined"
              className="timestamp-chip"
            />
          ) : (
            <Chip label={ago} size="small" variant="outlined" className="timestamp-chip" />
          )}
        </div>
        <div className="message-actions">
          {!!isOwnMessage && !pending && ['media', 'chat'].includes(message.type) && id && (
            <DeleteMessageButton room={room} id={id} />
          )}
        </div>
      </div>
      <div className="message-message">
        {message.type === 'actions' ? <ActionText text={text} /> : markdownContent}
        {!!imageSrc && <img src={imageSrc} alt="uploaded by user" />}
        {!!actionTurn?.finished && isOwnMessage && (
          <Box
            className="message-action-box"
            sx={{
              textAlign: 'center',
            }}
          >
            <Button onClick={() => setIsOpenDialog(true)} variant="outlined" size="small">
              <Typography>{t('playAgain')}</Typography>
            </Button>
            <GameOverScreen
              open={isOpenDialog}
              outcome={resolveFinishOutcome(actionTurn.description, {
                cum: t('cum'),
                ruined: t('ruined'),
                noCum: t('noCum'),
              })}
              close={closeDialog}
            />
          </Box>
        )}
      </div>
    </li>
  );
}
